  "lightning-datatable": {
    "description": "A table that displays rows and columns of data. [View in Component Library](https://developer.salesforce.com/docs/component-library/bundle/lightning-datatable)",
    "properties": {
      "columns": {
        "type": "readonly unknown[]",
        "description": "Array of the columns object that's used to define the data types. Required properties include 'label', 'fieldName', and 'type'. The default type is 'text'. See the Documentation tab for more information."
      },
      "columnWidthsMode": {
        "type": "any"
      },
      "data": {
        "type": "any",
        "description": "The array of data to be displayed."
      },
      "defaultSortDirection": {
        "type": "string | number",
        "description": "Specifies the default sorting direction on an unsorted column. Valid options include 'asc' and 'desc'. The default is 'asc' for sorting in ascending order."
      },
      "disabledRows": {
        "type": "any"
      },
      "draftValues": {
        "type": "any",
        "description": "The current values per row that are provided during inline edit."
      },
      "enableInfiniteLoading": {
        "type": "boolean",
        "description": "If present, you can load a subset of data and then display more when users scroll to the end of the table. Use with the onloadmore event handler to retrieve more data."
      },
      "errors": {
        "type": "any",
        "description": "Specifies an object containing information about cell level, row level, and table level errors. When it's set, error messages are displayed on the table accordingly."
      },
      "hideCheckboxColumn": {
        "type": "boolean",
        "description": "If present, the checkbox column for row selection is hidden."
      },
      "hideTableHeader": {
        "type": "any",
        "description": "If present, the table header is hidden."
      },
      "isLoading": {
        "type": "boolean",
        "description": "If present, a spinner is shown to indicate that more data is loading."
      },
      "keyField": {
        "type": "string | number",
        "description": "Required for better performance. Associates each row with a unique ID."
      },
      "loadMoreOffset": {
        "type": "number | string",
        "description": "Determines when to trigger infinite loading based on how many pixels the table's scroll position is from the bottom of the table. The default is 20."
      },
      "maxColumnWidth": {
        "type": "number | string",
        "description": "The maximum width for all columns. The default is 1000px."
      },
      "maxRowSelection": {
        "type": "number | string",
        "description": "The maximum number of rows that can be selected. Checkboxes are used for selection by default, and radio buttons are used when maxRowSelection is 1."
      },
      "minColumnWidth": {
        "type": "number | string",
        "description": "The minimum width for all columns. The default is 50px."
      },
      "renderConfig": {
        "type": "any"
      },
      "renderMode": {
        "type": "any"
      },
      "resizeColumnDisabled": {
        "type": "boolean",
        "description": "If present, column resizing is disabled."
      },
      "resizeStep": {
        "type": "number | string",
        "description": "The width to resize the column when a user presses left or right arrow. The default is 10px."
      },
      "rowNumberOffset": {
        "type": "number | string",
        "description": "Determines where to start counting the row number. The default is 0."
      },
      "selectedRows": {
        "type": "readonly unknown[]",
        "description": "Enables programmatic row selection with a list of key-field values."
      },
      "showRowNumberColumn": {
        "type": "boolean",
        "description": "If present, the row numbers are shown in the first column."
      },
      "singleRowSelectionMode": {
        "type": "any"
      },
      "sortedBy": {
        "type": "string | number",
        "description": "The column fieldName that controls the sorting order. Sort the data using the onsort event handler."
      },
      "sortedDirection": {
        "type": "string | number",
        "description": "Specifies the sorting direction. Sort the data using the onsort event handler. Valid options include 'asc' and 'desc'."
      },
      "suppressBottomBar": {
        "type": "any",
        "description": "If present, the footer that displays the Save and Cancel buttons is hidden during inline editing."
      },
      "title": {
        "type": "string | number",
        "description": "Displays tooltip text when the mouse moves over the element."
      },
      "wrapTableHeader": {
        "type": "any"
      },
      "wrapTextMaxLines": {
        "type": "any",
        "description": "This value specifies the number of lines after which the content will be cut off and hidden. It must be at least 1 or more. The text in the last line is truncated and shown with an ellipsis."
      }
    },
    "methods": {
      "getSelectedRows": {
        "type": "(...args: any[]) => any",
        "description": "Returns data in each selected row."
      },
      "openInlineEdit": {
        "type": "(...args: any[]) => any",
        "description": "Opens the inline edit panel for the datatable's currently active cell. If the active cell is not editable, then the panel is instead opened for the first editable cell in the table. Given two distinct cells, C_x and C_y, C_x is considered \"first\" in the cell ordering if the following condition evaluates to true: (C_x.rowIndex < C_y.rowIndex) || (C_x.rowIndex === C_y.rowIndex && C_x.columnIndex < C_y.columnIndex) If there is no data in the table or there are no editable cells in the table then calling this function results in a no-op."
      },
      "scrollToTop": {
        "type": "() => any",
        "description": "Scrolls to the top of the datatable."
      }
    },
    "events": {
      "cancel": {
        "type": "CustomEvent<any>",
        "description": "The event fired when the cancel button is pressed during inline editing. Doesn't bubble."
      },
      "cellchange": {
        "type": "CustomEvent<{ draftValues: any[] }>",
        "description": "An inline edit changed a cell."
      },
      "headeraction": {
        "type": "CustomEvent<{ action: any; columnDefinition: any }>",
        "description": "The event fired when a header action is selected, such as text wrapping, text clipping, or a custom header action. Doesn't bubble."
      },
      "loadmore": {
        "type": "CustomEvent<{ enableInfiniteLoading: boolean; isLoading: boolean; loadMoreOffset: number }>",
        "description": "The event fired when you scroll to the bottom of the table to load more data, until there are no more data to load. Doesn't bubble."
      },
      "resize": {
        "type": "CustomEvent<{ columnWidths: any; isUserTriggered: boolean }>",
        "description": "The event fired when the a table column is resized, which depends on which width mode you're using. Doesn't bubble."
      },
      "rowaction": {
        "type": "CustomEvent<{ action: any; row: any }>",
        "description": "A row action was clicked."
      },
      "rowselection": {
        "type": "CustomEvent<{ selectedRows: any[]; config?: { action?: string; value?: any } }>",
        "description": "The event fired when the row is selected. Doesn't bubble."
      },
      "save": {
        "type": "CustomEvent<{ draftValues: any[] }>",
        "description": "The event fired when data is saved during inline editing. Doesn't bubble."
      },
      "sort": {
        "type": "CustomEvent<{ fieldName: string; sortDirection: \"asc\" | \"desc\"; isMultiColumnSort?: boolean }>",
        "description": "The event fired when a column is sorted. Doesn't bubble."
      }
    }
  },
